BytesAre.example:
#include <cinux/memory.hpp>

using namespace cinux::base;

void CheckBlock() {
    const unsigned char kBlock[4] = {0xAA, 0xAA, 0xAA, 0xAA};
    const bool kAllSet = BytesAre(kBlock, 0xAA, sizeof kBlock);
    // kAllSet = true · 四个字节全是 0xAA
}

